#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxSumAfterOperation(vector<int>& nums) {
        int dp0 = 0, dp1 = 0;
        int ans = -1e9;
        for (int x : nums) {
            int sq = x * x;
            dp1 = max({sq, dp0 + sq, dp1 + x});
            dp0 = max(x, dp0 + x);
            ans = max(ans, dp1);
        }
        return ans;
    }
};

class Solution {
    public int maxSumAfterOperation(int[] nums) {
        int dp0 = 0, dp1 = 0;
        int ans = Integer.MIN_VALUE;
        for (int x : nums) {
            int sq = x * x;
            dp1 = Math.max(sq, Math.max(dp0 + sq, dp1 + x));
            dp0 = Math.max(x, dp0 + x);
            ans = Math.max(ans, dp1);
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var maxSumAfterOperation = function(nums) {
    let dp0 = 0, dp1 = 0;
    let ans = -Infinity;
    for (const x of nums) {
        const sq = x * x;
        dp1 = Math.max(sq, dp0 + sq, dp1 + x);
        dp0 = Math.max(x, dp0 + x);
        ans = Math.max(ans, dp1);
    }
    return ans;
};
